const killed = new Set(['Rat','Man','Goblin','Giant spider','Imp','Duck','Giant rat','Woman']);
const kills = [];
const endTime = Date.now() + 200000;
const log = (m) => console.log(m);
const heal = async () => { const f = sdk.findInventoryItem(/shrimps|bread/i); if (f && sdk.getState().player.currentHitpoints <= 8) { try { await bot.eatFood(f); } catch {} } };
const freshAt = () => sdk.getNearbyNpcs().filter(n => (n.options || []).includes('Attack') && n.combatLevel > 0 && n.reachable !== false && !n.inCombat && !killed.has(n.name));
const grabCoins = async () => { try { const c = sdk.findGroundItem(/^coins$/i, { reachable: true }); if (c) await bot.pickupItem(c); } catch {} };
const killAll = async () => {
  let idle = 0;
  while (Date.now() < endTime - 15000) {
    const f = freshAt();
    if (!f.length) { idle++; if (idle > 1) return; await sdk.waitForTicks(6); continue; }
    idle = 0;
    const t = f.sort((a, b) => a.combatLevel - b.combatLevel)[0];
    const r = await bot.attack(t, 8000);
    if (r && r.success) {
      for (let i = 0; i < 22; i++) {
        await sdk.waitForTicks(3);
        if (!sdk.getNearbyNpcs().find(n => n.index === t.index)) { killed.add(t.name); kills.push(t.name + ' lv' + t.combatLevel); break; }
        await heal();
      }
    } else { killed.add(t.name); }
    await grabCoins();
  }
};
const stops = [[3254, 3258], [3225, 3300], [3222, 3218], [3107, 3157]];
for (const [x, z] of stops) {
  if (Date.now() > endTime - 20000) break;
  try { await bot.walkTo(x, z, 8); } catch { log('walk fail ' + x + ',' + z); }
  await killAll();
}
// Al Kharid if we have 10 coins
const s = sdk.getState();
let coins = sdk.findInventoryItem(/^coins$/i);
let alkDone = false;
if (coins && (coins.quantity || 1) >= 10) {
  try {
    await bot.walkTo(3282, 3176, 8);
    await killAll();
    alkDone = true;
  } catch {}
}
return { kills, killed: [...killed], hp: s.player.currentHitpoints, pos: [s.player.worldX, s.player.worldZ] };
